using System.Collections.Generic;
using System.Drawing;
namespace WinterDesk {
internal enum SquirrelState { Entering,Running,Anticipating,Jumping,Landing,Climbing,Mounting,Held,Falling,Done }
internal sealed class SquirrelMotion {
 internal double X,Y,Age,Time,StartX,StartY,GoalX,GoalY,Offset,TargetOffset,Duration=.8,Arc=90,VY,ClimbDistance,ClimbOffset,WallOffset,ClimbStride,ClimbSpeed;internal float Scale;internal int Direction=1,Hops,EdgeSide=-1;internal IntPtr Support,Target;internal bool WallJump;internal SquirrelState State=SquirrelState.Entering;readonly Random random;readonly double screenLeft,screenRight;double grabX,grabY,mountStartX;bool exiting;
 internal SquirrelMotion(Ledge first,double x,float scale,int seed):this(first,x,scale,seed,0,1920){}
 internal SquirrelMotion(Ledge first,double x,float scale,int seed,double left,double right,double top=0,int entryDirection=0){random=new Random(seed);screenLeft=left;screenRight=right;Scale=scale;Support=first.Handle;Y=first.Bounds.Top;Direction=entryDirection==0?(first.Bounds.Left-left<=right-first.Bounds.Right?1:-1):entryDirection;X=Direction>0?left-100*scale:right+100*scale;Offset=X-first.Bounds.Left;}
 void Change(SquirrelState state){State=state;Age=0;}
 internal PointF RenderOrigin(int width,int height){if(State==SquirrelState.Climbing)return new PointF((float)(X-(Direction>0?198:22)*Scale),(float)(Y-140*Scale));if(State==SquirrelState.Mounting){double t=Math.Min(1,Age/.55),grip=Direction>0?198:22;return new PointF((float)(X-(grip+(110-grip)*t)*Scale),(float)(Y-(140+177*t)*Scale));}return new PointF((float)(X-width*.5),(float)(Y-height+3*Scale));}
 internal void Grab(double x,double y){int h=(State==SquirrelState.Climbing||State==SquirrelState.Mounting)?320:170;var origin=RenderOrigin((int)(220*Scale),(int)(h*Scale));X=origin.X+110*Scale;Y=origin.Y+h*Scale-3*Scale;grabX=x-X;grabY=y-Y;Support=IntPtr.Zero;WallJump=false;VY=0;Change(SquirrelState.Held);}
 internal void Drag(double x,double y){X=x-grabX;Y=y-grabY;}
 internal void Drop(){Support=IntPtr.Zero;WallJump=false;VY=0;Change(SquirrelState.Falling);}
 double Edge(Ledge window){return EdgeSide<0?window.Bounds.Left+1:window.Bounds.Right-1;}
 bool Blocked(Ledge window,double x,double y){foreach(var b in window.Blockers)if(b.Contains((int)x,(int)y))return true;return false;}
 void BeginJump(Ledge destination,double x,double y,bool wall){Target=destination.Handle;TargetOffset=x-destination.Bounds.Left;GoalX=x;GoalY=y;StartX=X;StartY=Y;WallJump=wall;if(wall)WallOffset=y-destination.Bounds.Top;if(Math.Abs(x-X)>2*Scale)Direction=x>X?1:-1;Duration=.55+Math.Abs(x-X)/(650*Scale)+Math.Abs(y-Y)/(650*Scale);Arc=(75+random.NextDouble()*30)*Scale;if(wall)Arc=Math.Max(Arc,Math.Min(180*Scale,Math.Abs(y-Y)*.22));Change(SquirrelState.Anticipating);}
 void Plan(List<Ledge> ledges){var current=ledges.Find(l=>l.Handle==Support);if(current==null){Drop();return;}if(Time>=45){exiting=true;Direction=X-screenLeft<screenRight-X?-1:1;}
  double distance=(175+random.NextDouble()*75)*Scale;
  if(!exiting&&Support==new IntPtr(-2)){Ledge chosen=null;double best=double.MaxValue,edge=0;int side=-1;foreach(var l in ledges){if(l.Handle==Support||l.Bounds.Top>=Y-20*Scale)continue;int nextSide=X<l.Bounds.Left+l.Bounds.Width*.5?-1:1;double ex=nextSide<0?l.Bounds.Left+1:l.Bounds.Right-1,dist=Math.Abs(ex-X);double cy=Math.Max(l.Bounds.Top+Math.Min(l.Bounds.Height*.5,70*Scale),Math.Min(l.Bounds.Bottom-18*Scale,Y-170*Scale));if(Blocked(l,ex,cy))continue;if(dist<best){chosen=l;best=dist;edge=ex;side=nextSide;}}
   if(chosen!=null){Direction=edge>=X?1:-1;if(best<=290*Scale){EdgeSide=side;double catchY=Math.Max(chosen.Bounds.Top+Math.Min(chosen.Bounds.Height*.5,70*Scale),Math.Min(chosen.Bounds.Bottom-18*Scale,Y-170*Scale));BeginJump(chosen,edge,catchY,true);return;}double gx=X+Direction*Math.Min(distance,best-100*Scale);BeginJump(current,gx,Y,false);return;}}
  if(!exiting){foreach(var l in ledges){if(l.Handle==Support||l.Handle==new IntPtr(-2)||Math.Abs(l.Bounds.Top-Y)>210*Scale)continue;double gx=Math.Max(l.Bounds.Left+18*Scale,Math.Min(l.Bounds.Right-18*Scale,X+Direction*distance));if(Math.Abs(gx-X)<=290*Scale&&l.Supports(gx)){BeginJump(l,gx,l.Bounds.Top,false);return;}}}
  double next=X+Direction*distance;if(current.Handle!=new IntPtr(-2)&&!current.Supports(next)){if(exiting){X=Direction>0?current.Bounds.Right+10*Scale:current.Bounds.Left-10*Scale;Drop();return;}Direction=-Direction;next=Math.Max(current.Bounds.Left+18*Scale,Math.Min(current.Bounds.Right-18*Scale,X+Direction*distance));}BeginJump(current,next,Y,false);
 }
 internal void Tick(double dt,List<Ledge> ledges,double left,double right){if(State==SquirrelState.Done)return;dt=Math.Max(0,Math.Min(.05,dt));Time+=dt;Age+=dt;if(State==SquirrelState.Held)return;
  if(State==SquirrelState.Falling){double old=Y;VY+=1000*Scale*dt;Y+=VY*dt;Ledge land=null;foreach(var l in ledges)if(l.Supports(X)&&old<=l.Bounds.Top&&Y>=l.Bounds.Top&&(land==null||l.Bounds.Top<land.Bounds.Top))land=l;if(land!=null){Y=land.Bounds.Top;Support=land.Handle;Offset=X-land.Bounds.Left;VY=0;Change(SquirrelState.Landing);}if(Y>40000)Change(SquirrelState.Done);return;}
  if(exiting&&(X<left-110*Scale||X>right+110*Scale)){Change(SquirrelState.Done);return;}
  if(State==SquirrelState.Climbing||State==SquirrelState.Mounting){var window=ledges.Find(l=>l.Handle==Target);if(window==null){Drop();return;}Direction=EdgeSide<0?1:-1;double edge=Edge(window);
   if(State==SquirrelState.Climbing){X=edge;double move=Math.Min(Math.Max(0,ClimbOffset),ClimbSpeed*dt);ClimbOffset-=move;Y=window.Bounds.Top+ClimbOffset;ClimbDistance+=move;if(Y<=window.Bounds.Top+.1){Y=window.Bounds.Top;mountStartX=edge;Change(SquirrelState.Mounting);}}
   else{Y=window.Bounds.Top;mountStartX=edge;double t=Math.Min(1,Age/.55),smooth=t*t*(3-2*t);double onTop=EdgeSide<0?window.Bounds.Left+Math.Min(window.Bounds.Width*.35,85*Scale):window.Bounds.Right-Math.Min(window.Bounds.Width*.35,85*Scale);X=mountStartX+(onTop-mountStartX)*smooth;if(t>=1){Support=Target;Offset=X-window.Bounds.Left;WallJump=false;Change(SquirrelState.Landing);}}return;}
  if(State==SquirrelState.Jumping){var goal=ledges.Find(l=>l.Handle==Target);if(goal==null){Drop();return;}GoalX=WallJump?Edge(goal):goal.Bounds.Left+TargetOffset;if(WallJump)GoalY=Math.Max(goal.Bounds.Top+Math.Min(goal.Bounds.Height*.5,70*Scale),Math.Min(goal.Bounds.Bottom-18*Scale,goal.Bounds.Top+WallOffset));else GoalY=goal.Bounds.Top;double t=Math.Min(1,Age/Duration);X=StartX+(GoalX-StartX)*t;Y=StartY+(GoalY-StartY)*t-4*t*(1-t)*Arc;if(t>=1){Hops++;if(WallJump){Support=Target;X=Edge(goal);Direction=EdgeSide<0?1:-1;ClimbDistance=0;ClimbOffset=Y-goal.Bounds.Top;ClimbStride=Math.Max(150*Scale,ClimbOffset/3);ClimbSpeed=Math.Max(320*Scale,ClimbOffset/2.2);Change(SquirrelState.Climbing);}else{Support=Target;Offset=TargetOffset;Change(SquirrelState.Landing);}}return;}
  var support=ledges.Find(l=>l.Handle==Support);if(support==null){Drop();return;}X=support.Bounds.Left+Offset;Y=support.Bounds.Top;
  if(State==SquirrelState.Anticipating){StartX=X;StartY=Y;if(Age>=.07)Change(SquirrelState.Jumping);return;}if(State==SquirrelState.Landing){if(Age>=.10)Change(SquirrelState.Running);return;}if(Age>=.12)Plan(ledges);
 }
 internal int Frame{get{if(State==SquirrelState.Climbing)return 128+(int)(ClimbDistance/Math.Max(1,ClimbStride)*8)%8;if(State==SquirrelState.Mounting)return 136+Math.Min(7,(int)(Age/.55*8));if(State==SquirrelState.Held||State==SquirrelState.Falling)return 55+(int)(Time*20)%32;if(State==SquirrelState.Anticipating)return 32+Math.Min(7,(int)(Age/.07*8));if(State==SquirrelState.Jumping)return 40+Math.Min(63,(int)(Age/Duration*64));if(State==SquirrelState.Landing)return 104+Math.Min(23,(int)(Age/.10*24));return (int)(Time*32)%32;}}
}
internal static class SquirrelRouteBuilder {
 internal static List<Ledge> Build(List<Ledge> roofs,Rectangle area,int floor,float scale){var routes=new List<Ledge>(roofs);routes.Add(new Ledge{Handle=new IntPtr(-2),Bounds=new Rectangle(area.Left-1000,floor,area.Width+2000,1)});return routes;}
}
internal sealed class SquirrelActor:IDisposable {internal readonly Layer Window=new Layer();internal readonly SpriteCache<int> Frames=new SpriteCache<int>(64,8388608);internal SquirrelMotion Motion;internal Sprite CurrentImage;internal int Frame=-1;public void Dispose(){Window.Dispose();Frames.Clear();}}
internal sealed partial class Controller {
 readonly WindowSnowmanSchedule squirrelSchedule=new WindowSnowmanSchedule(300);SquirrelActor squirrel;List<Ledge> cachedSquirrelRoutes;int squirrelRoutesRevision=-1;
 void ClearSquirrel(){cachedSquirrelRoutes=null;if(squirrel!=null){squirrel.Dispose();squirrel=null;}}
 List<Ledge> SquirrelRoutes(){if(cachedSquirrelRoutes!=null&&squirrelRoutesRevision==sceneRevision)return cachedSquirrelRoutes;var area=System.Windows.Forms.SystemInformation.VirtualScreen;squirrelRoutesRevision=sceneRevision;return cachedSquirrelRoutes=SquirrelRouteBuilder.Build(ledges,area,System.Windows.Forms.Screen.PrimaryScreen.WorkingArea.Bottom,.65f*Scale(System.Windows.Forms.Screen.PrimaryScreen));}
 void SpawnSquirrel(){if(squirrel!=null)return;var area=System.Windows.Forms.SystemInformation.VirtualScreen;var routes=SquirrelRoutes();var ground=routes[routes.Count-1];squirrel=new SquirrelActor{Motion=new SquirrelMotion(ground,0,.65f*Scale(System.Windows.Forms.Screen.PrimaryScreen),random.Next(),area.Left,area.Right,area.Top,random.Next(2)==0?1:-1)};var a=squirrel;a.Window.SetInput(true);a.Window.Hit=delegate(int x,int y){var image=a.CurrentImage;return image!=null&&x>=0&&y>=0&&x<image.Width&&y<image.Height&&((uint)image.Pixel(x,y)>>24)>32;};a.Window.MouseDown=delegate(int x,int y){a.Motion.Grab(a.Window.X+x,a.Window.Y+y);};a.Window.MouseDrag=delegate(int x,int y){if(a.Motion.State==SquirrelState.Held)a.Motion.Drag(a.Window.X+x,a.Window.Y+y);};a.Window.MouseUp=delegate(int x,int y){if(a.Motion.State==SquirrelState.Held)a.Motion.Drop();};}
 void AnimateSquirrel(double dt,double now){if(squirrel==null)return;var m=squirrel.Motion;var extent=System.Windows.Forms.SystemInformation.VirtualScreen;var routes=SquirrelRoutes();if(m.State==SquirrelState.Held){Native.POINT cursor;Native.GetCursorPos(out cursor);if((Native.GetAsyncKeyState(1)&0x8000)!=0)m.Drag(cursor.X,cursor.Y);else{m.Drop();Native.ReleaseCapture();}}m.Tick(dt,routes,extent.Left,extent.Right);if(m.State==SquirrelState.Done){ClearSquirrel();return;}if(screens.Exists(r=>r.FullScreen&&r.Screen.Bounds.Contains((int)m.X,(int)m.Y))){squirrel.Window.Show(false);return;}int frame=m.Frame+(m.Direction<0?256:0);Sprite image;if(!squirrel.Frames.TryGetValue(frame,out image)){using(var b=DrawnArt.Squirrel(m.Frame,m.Scale,m.Direction))image=new Sprite(b);squirrel.Frames.Add(frame,image);}squirrel.CurrentImage=image;var origin=m.RenderOrigin(image.Width,image.Height);int x=(int)origin.X,y=(int)origin.Y;if(frame!=squirrel.Frame){squirrel.Window.Paint(image,x,y);squirrel.Frame=frame;}else squirrel.Window.Move(x,y);var support=routes.Find(l=>l.Handle==m.Support);squirrel.Window.Clip(new Rectangle(x,y,image.Width,image.Height),support==null?new List<Rectangle>():support.Blockers);squirrel.Window.Show(true);}
}
}
